function resetJourneyMechanics(id){const j=journeys[id];if(!j)return;for(let i=0;i<j.steps.length;i++)if(j.steps[i].mechanic)resetMechanic(j.steps[i].mechanic,i)}
function setMode(mode){state.mode=mode==="dark"?"dark":"normal";save();app.dataset.igniteMode=state.mode;renderHome()}
function generateJourney(id,targetSteps,bias={}){const base=journeys[id==="dark"?"dark":"normal"];const target=Math.max(3,Math.min(12,Number(targetSteps)||5));const closing=base.steps[base.steps.length-1];const opening=base.steps[0];const pool=base.steps.slice(1,-1);const weights=bias.weights||{};const weightFor=s=>{if(s.mechanic==="card"||s.mechanic==="explicit-card")return weights.Talk||1;if(s.mechanic==="rps")return weights.RPS||1;if(s.mechanic==="tod"||s.mechanic==="intimate-tod")return weights.TruthDare||1;if(s.title==="Roleplay")return weights.Roleplay||1;return 1};const chosen=[];let availablePool=pool.slice();while(chosen.length<target-2){if(!availablePool.length)availablePool=pool.slice();let candidates=availablePool.filter(s=>!chosen.length||s.mechanic!==chosen[chosen.length-1].mechanic);if(!candidates.length)candidates=availablePool.slice();const weighted=[];for(const s of candidates){const n=Math.max(1,Math.round(weightFor(s)));for(let i=0;i<n;i++)weighted.push(s)}const picked=weighted[Math.floor(Math.random()*weighted.length)]||candidates[0];chosen.push(picked);const index=availablePool.indexOf(picked);if(index>=0)availablePool.splice(index,1);}return{...JSON.parse(JSON.stringify(base)),steps:[JSON.parse(JSON.stringify(opening)),...chosen.map(s=>JSON.parse(JSON.stringify(s))),JSON.parse(JSON.stringify(closing))]}}
function startJourney(id,options={}){const selected=id==="dark"?"dark":(id==="normal"?"normal":(state.mode==="dark"?"dark":"normal"));const preferred=getPreferences().steps;const target=Math.max(3,Math.min(12,Number(options.targetSteps)||Number(preferred)||5));const bias=options.bias||{};progressionStartJourney(selected);state.__journeyTargetSteps=target;state.view="generating";save();render();window.setTimeout(()=>{resetJourneyMechanics(selected);state.currentJourney=generateJourney(selected,target,bias);state.step=0;delete state.__journeyTargetSteps;if(!state.names.p1.trim()||!state.names.p2.trim())setView("names");else setView("intro")},650)}
function begin(){const consent=document.querySelector("#consent");if(state.currentJourney.id==="dark"&&(!consent||!consent.checked))return;setView("session")}
function next(award=true){const current=state.currentJourney.steps[state.step];if(award&&current.kind==="ritual")completeRitual(state.currentJourney.id,state.step);else if(award&&current.kind==="activity")completeActivity(state.currentJourney.id,state.step);if(state.step>=state.currentJourney.steps.length-1){completeJourney(state.currentJourney.id,{title:state.currentJourney.title,subtitle:state.currentJourney.subtitle,steps:state.currentJourney.steps});state.view="complete";save();render();return}state.step++;save();render()}
function skip(){next(false)}
function exitSession(){save();setView("home")}
function restart(){const current=state.currentJourney;if(!current){setView("home");return}const id=current.id;resetJourneyMechanics(id);state.currentJourney=JSON.parse(JSON.stringify(current));state.step=0;setView("intro")}
function saveNames(form){const d=new FormData(form);state.names.p1=String(d.get("p1")||"").trim();state.names.p2=String(d.get("p2")||"").trim();state.names.couple="";state.relationship=String(d.get("relationship")||"Couple");if(!state.relationshipSince)state.relationshipSince=new Date().toISOString();save();if(state.currentJourney)setView("intro");else setView("home")}
app.addEventListener("change",function(e){if(e.target?.id==="topic-source-import"){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{importContentSource(JSON.parse(reader.result))}catch{alert("Invalid source JSON.")}};reader.readAsText(file)}});
app.addEventListener("click",function(e){const settingsLink=e.target.closest(".profile-v1 .topbar [data-action=\"settings\"]");if(settingsLink){setView("settings");return}const ending=e.target.closest("[data-ending]");if(ending){recordInteraction("session-ending",ending.dataset.ending);e.target.closest(".ending-vibes")?.querySelectorAll("button").forEach(b=>b.classList.remove("primary"));ending.classList.add("primary");return}const el=e.target.closest("[data-action]");if(!el)return;const a=el.dataset.action;if(a==="enter"){sessionStorage.setItem("ignite-welcome-seen","1");if(state.names.p1.trim()&&state.names.p2.trim()){state.view="home";save();render();}else{state.view="names";save();render();}}else if(a==="home")setView("home");else if(a==="settings")setView("settings");else if(a==="mode")setMode(el.dataset.mode);else if(a==="profile")setView("profile");else if(a==="memories")setView("memories");else if(a==="memory-capture")setView("memory-capture");else if(a==="bond")setView("bond");else if(a==="preferences")setView("preferences");else if(a==="topics")setView("topics");else if(a==="dynamic"){const ctx=dynamicContext(getLevelInfo(getProgress().xp).level);startJourney(ctx.journeyId,{targetSteps:ctx.targetSteps,bias:ctx.bias});}else if(a==="save-memory"){saveMemory({journey:state.currentJourney?.title||"Journey",xp:getProgress().xp,moment:"A moment together"});setView("home");}else if(a==="minigames"){state.__minigameActive=null;setView("minigames")}else if(a==="minigames-menu"){state.__minigameActive=null;render()}else if(a==="journey")setView("journey");else if(a==="journey-detail"){state.__selectedJourney=Number(el.dataset.index);setView("journey-detail")}else if(a==="journey-back"){state.__selectedJourney=null;setView("journey")}else if(a==="start")startJourney(el.dataset.journey);else if(a==="surprise"){const ctx=surpriseContext(getLevelInfo(getProgress().xp).level);startJourney(ctx.journeyId,{targetSteps:ctx.targetSteps,bias:ctx.bias});}else if(a==="continue")setView("session");else if(a==="begin")begin();else if(a==="next")next();else if(a==="skip")skip();else if(a==="exit")exitSession();else if(a==="again")restart()});
app.addEventListener("click",function(e){const el=e.target.closest("[data-mechanic]");if(!el)return;const s=state.currentJourney&&state.currentJourney.steps[state.step];if(!s||!s.mechanic)return;const a=el.dataset.mechanic;if(a==="guess"||a==="pick")mechanicAction(s.mechanic,state.step,a,el.dataset.value);else if(a==="next-round"||a==="rps-next")mechanicAction(s.mechanic,state.step,"next");else if(a==="draw-card"||a==="next-card"){mechanicAction(s.mechanic,state.step,"draw");if(a==="next-card"){recordOneMore();recordInteraction("one-more",state.mode==="dark"?"Intimate":"Romantic")}}else if(a==="tod-mode")mechanicAction(s.mechanic,state.step,"toggle",el.dataset.value);else if(a==="tod-draw"||a==="next-tod")mechanicAction(s.mechanic,state.step,"draw");render()});
app.addEventListener("click",function(e){const mood=e.target.closest("[data-mood]");if(mood){handleMoodClick(mood);renderHome();return}const vibeHome=e.target.closest("[data-vibe-home]");if(vibeHome){handleVibeClick({dataset:{vibe:vibeHome.dataset.vibeHome}});recordVibe(vibeHome.dataset.vibeHome);renderHome();return}const vibe=e.target.closest("[data-vibe]");if(vibe){handleVibeClick(vibe);recordVibe(vibe.dataset.vibe);renderPreferences();return}const el=e.target.closest("[data-mini-open]");if(!el)return;state.__minigameActive=el.dataset.miniOpen;recordMinigamePlayed(state.__minigameActive);openMinigame(state.__minigameActive,state.mode);render()});
app.addEventListener("click",function(e){const el=e.target.closest("[data-mini]");if(!el)return;const action=el.dataset.mini;const value=action==="chess-square"?el.dataset.index:el.dataset.value;minigameAction(action,value);render();if((action==="snake-roll"||action==="snake-skip")&&state.__minigameActive==="snake")window.__igniteAnimateSnakeMove?.()});
app.addEventListener("click",function(e){
 const b=e.target.closest("[data-bond-action]");
 if(b){const s=readBond(),type=b.dataset.bondType||"daily";if(b.dataset.bondAction==="new"){s[type+"Current"]=pickBond(type,s[type+"Current"]||"");writeBond(s);renderBond()}if(b.dataset.bondAction==="favorite"){const current=s.dailyCurrent||pickBond("daily");if(!s.favorites.includes(current))s.favorites.unshift(current);writeBond(s);renderBond()}return}
 const g=e.target.closest("[data-bond-goal]");if(g){const s=readBond(),i=Number(g.dataset.bondGoal);if(s.goals[i])s.goals[i].done=g.checked;writeBond(s);renderBond()}
});
app.addEventListener("click",function(e){
 const category=e.target.closest("[data-topic-category]");
 if(category){state.__topicCategory=category.dataset.topicCategory;renderTopics();return}
 const topicAction=e.target.closest("[data-topic-action]");
 if(topicAction){if(topicAction.dataset.topicAction==="export"){exportTopicsJS().catch(()=>alert("Export failed."));return}if(topicAction.dataset.topicAction==="import-json"){document.querySelector("#topic-source-import")?.click();return}}
 const del=e.target.closest("[data-topic-delete]");
 if(del){const k=del.dataset.topicDelete,i=Number(del.dataset.topicIndex),x=readContent();if(Number.isInteger(i)&&Array.isArray(x[k])){const value=x[k][i];x[k].splice(i,1);saveContent(x);try{const custom=JSON.parse(localStorage.getItem("ignite-custom-topics-v1")||"null")||{};if(Array.isArray(custom[k])){custom[k]=custom[k].filter(v=>v!==value);localStorage.setItem("ignite-custom-topics-v1",JSON.stringify(custom))}}catch{}}renderTopics();return}
 const roleDel=e.target.closest("[data-role-delete]");
 if(roleDel){const k=state.__topicCategory||"roleplayNormal",i=Number(roleDel.dataset.roleDelete),x=readContent();if(Number.isInteger(i)&&Array.isArray(x[k])){x[k].splice(i,1);saveContent(x)}renderTopics();return}
 const sceneDel=e.target.closest("[data-scene-delete]");
 if(sceneDel){const k=state.__topicCategory||"roleplayNormal",ri=Number(sceneDel.dataset.sceneDelete),si=Number(sceneDel.dataset.sceneIndex),x=readContent();if(x[k]?.[ri]?.items?.[si]){x[k][ri].items.splice(si,1);saveContent(x)}renderTopics();return}
});
app.addEventListener("submit",function(e){if(e.target.matches("#name-form,#settings-form")){e.preventDefault();saveNames(e.target);return}if(e.target.matches("#topic-form")){e.preventDefault();const data=new FormData(e.target),k=String(data.get("category")||"normalCards"),v=String(data.get("text")||"").trim(),x=readContent();if(v&&!x[k].includes(v)){x[k].push(v);saveContent(x);try{const custom=JSON.parse(localStorage.getItem("ignite-custom-topics-v1")||"null")||{};for(const key of TOPIC_MANAGER_KEYS.filter(k=>!ROLE_KEYS.includes(k))){if(!Array.isArray(custom[key]))custom[key]=[]}if(!custom[k].includes(v))custom[k].push(v);localStorage.setItem("ignite-custom-topics-v1",JSON.stringify(custom))}catch{}}renderTopics();return}
if(e.target.matches("#role-form")){e.preventDefault();const data=new FormData(e.target),k=state.__topicCategory||"roleplayNormal",x=readContent();x[k].push(cleanRole({id:"custom-"+Date.now(),emoji:data.get("emoji"),name:data.get("name"),desc:data.get("desc"),items:[]}));saveContent(x);renderTopics();return}
if(e.target.matches("[data-role-scene-form]")){e.preventDefault();const ri=Number(e.target.dataset.roleSceneForm),k=state.__topicCategory||"roleplayNormal",data=new FormData(e.target),x=readContent();if(x[k]?.[ri])x[k][ri].items.push({context:String(data.get("context")||"").trim(),challenge:String(data.get("challenge")||"").trim()});saveContent(x);renderTopics();return}
if(e.target.matches("#preferences-form")){e.preventDefault();handlePreferenceSubmit(e.target);setView("minigames");return}if(e.target.matches("#bond-goal-form")){e.preventDefault();const s=readBond(),goal=String(new FormData(e.target).get("goal")||"").trim();if(goal){s.goals.unshift({text:goal,done:false});writeBond(s)}renderBond();return}if(e.target.matches("#memory-form")){e.preventDefault();const form=e.target,data=new FormData(form),moment=String(data.get("moment")||"A moment together").trim(),note=String(data.get("note")||"").trim(),file=form.querySelector("input[name=photo]")?.files?.[0];const finish=photo=>{saveMemory({journey:state.currentJourney?.title||"Manual Memory",xp:getProgress().xp,moment,note,photo:photo||""});recordMemorySaved();recordInteraction("memory-save");setView("memories")};if(file&&file.size>1024*1024){alert("Photo terlalu besar. Gunakan foto maksimal 1 MB.");return}if(file){const reader=new FileReader();reader.onload=()=>finish(String(reader.result||""));reader.readAsDataURL(file)}else finish("")}});
clearAllTopicStorageOnce();load();if(!sessionStorage.getItem("ignite-welcome-seen")){state.view="welcome"}else if(!state.names.p1.trim()||!state.names.p2.trim()){state.view="names"}else if(state.view==="names"){state.view="home"}initAccessibility(app);render();
